def primeFactors(n: Int): List[Int] = {
  def loop(n: Int, f: Int): List[Int] = {
    if (n == 1) Nil
    else if (n % f == 0) f :: loop(n / f, f)
    else loop(n, f + 1)
  }
  loop(n, 2)
}
val nums = List(315, 385, 495)
val primeFactorLists = nums.map(primeFactors)
