```csharp
using Windows.Devices.Sensors;
public class StepCounter
{
    private Accelerometer accelerometer;
    private int stepCount;
    public StepCounter()
    {
        accelerometer = Accelerometer.GetDefault();
        accelerometer.ReportInterval = accelerometer.MinimumReportInterval;
        accelerometer.ReadingChanged += Accelerometer_ReadingChanged;
    }
    private void Accelerometer_ReadingChanged(Accelerometer sender, AccelerometerReadingChangedEventArgs args)
    {
        double acceleration = Math.Sqrt(Math.Pow(args.Reading.AccelerationX, 2) + Math.Pow(args.Reading.AccelerationY, 2) + Math.Pow(args.Reading.AccelerationZ, 2));
        if (acceleration > 1.2)
        {
            stepCount++;
        }
    }
    public int GetStepCount()
    {
        return stepCount;
    }
    public void Reset()
    {
        stepCount = 0;
    }
}
```
This code initializes the accelerometer, sets its report interval to the minimum value, and subscribes to its `ReadingChanged` event. When the event is fired, the code calculates the acceleration magnitude and increments the step count if the acceleration is above a certain threshold.
