```csharp
public class FitnessTracker
{
    private StepCounter stepCounter;
    private double strideLength;
    private double weight;
    private double height;
    public FitnessTracker(double strideLength, double weight, double height)
    {
        stepCounter = new StepCounter();
        this.strideLength = strideLength;
        this.weight = weight;
        this.height = height;
    }
    public int GetStepCount()
    {
        return stepCounter.GetStepCount();
    }
    public double GetDistanceTraveled()
    {
        return stepCounter.GetStepCount() * strideLength;
    }
    public double GetCaloriesBurned()
    {
        double distance = GetDistanceTraveled();
        double metabolicRate = CalculateMetabolicRate();
        double caloriesPerMile = 0.57 * weight;
        return (caloriesPerMile * distance / 1609.34) * metabolicRate;
    }
    private double CalculateMetabolicRate()
    {
        double BMR;
        if (weight <= 0 || height <= 0)
        {
            return 0;
        }
        else
        {
            BMR = 10 * weight + 6.25 * height - 5 * 25 + 5;
        }
        return BMR;
    }
}
