```cpp
#include <iostream>
#include <vector>
std::vector<double> lbs_to_kg(const std::vector<double>& lbs) {
    std::vector<double> kg(lbs.size());
    for (int i = 0; i < lbs.size(); ++i) {
        kg[i] = lbs[i] * 0.453592;
    }
    return kg;
}
int main() {
    std::vector<double> weights_lbs = {10.0, 20.0, 30.0};
    std::vector<double> weights_kg = lbs_to_kg(weights_lbs);
    for (int i = 0; i < weights_lbs.size(); ++i) {
