    // Display the scrambled word
    cout << "Unscramble the word: " << word << endl;
    // Set the time limit to 30 seconds
    int timeLimit = 30;
    auto startTime = chrono::high_resolution_clock::now();
    // Get user input
    string guess;
    cout << "Enter your guess: ";
    cin >> guess;
    // Check if the guess is correct
    if (guess == words[index]) {
        auto endTime = chrono::high_resolution_clock::now();
        auto elapsedTime = chrono::duration_cast<chrono::seconds>(endTime - startTime).count();
        cout << "You unscrambled the word in " << elapsedTime << " seconds." << endl;
        // Ask for a synonym
        string synonym;
        cout << "Provide a synonym for the word: ";
        cin >> synonym;
